<section><h1>Appearance</h1><form method="post" action="<?= dts_escape(site_url('system_settings/appearance')) ?>" class="form-grid"><label>Theme scope<select name="themeScope"><option value="device" <?= ($settings['themeScope']??'')==='device'?'selected':'' ?>>Device</option><option value="shared" <?= ($settings['themeScope']??'')==='shared'?'selected':'' ?>>Shared</option></select></label><label>Color mode<select name="colorMode"><option value="light" <?= ($settings['colorMode']??'')==='light'?'selected':'' ?>>Light</option><option value="dark" <?= ($settings['colorMode']??'')==='dark'?'selected':'' ?>>Dark</option></select></label><label>Color theme<input name="colorTheme" maxlength="30" value="<?= dts_escape($settings['colorTheme']??'default') ?>"></label><button type="submit">Save appearance</button></form></section>
